def parse_pairs(s: str) -> dict:
    """
    Parse a string of semicolon-separated ``key=value`` pairs into a dictionary.
    Empty segments are ignored. If the input string is empty, an empty dictionary
    is returned.

    Examples
    --------
    >>> parse_pairs('a=1;b=2')
    {'a': '1', 'b': '2'}
    >>> parse_pairs('a=1;;b=2')
    {'a': '1', 'b': '2'}
    >>> parse_pairs('')
    {}
    """
    if not s:
        return {}

    result = {}
    for segment in s.split(';'):
        segment = segment.strip()
        if not segment:
            continue
        if '=' not in segment:
            continue
        key, value = segment.split('=', 1)
        result[key] = value
    return result

